// Markup lifted verbatim from _source/playbook.html <body>. Changes: the
// scroll-spy <script> moved into a useEffect in page.jsx (innerHTML never
// executes scripts), assets/ -> /assets/, and the cross-links repointed to
// the Next routes. Injected with dangerouslySetInnerHTML so the raw
// class="" attributes are parsed as HTML rather than by JSX.
const playbookHtml = "\n<div class=\"shell\">\n\n  <!-- ============= NAV ============= -->\n  <aside class=\"nav\">\n    <div class=\"nav-brand\">\n      <img src=\"/assets/icon-indigo.png\" alt=\"\" />\n      <div>\n        <div class=\"wm\">PRIVEXBOT</div>\n        <div class=\"sub\">Social Playbook \u00b7 v1</div>\n      </div>\n    </div>\n\n    <div class=\"nav-label\">Playbook</div>\n    <a href=\"#thesis\"><span class=\"num\">\u00a701</span><span>Thesis</span></a>\n    <a href=\"#strategy\"><span class=\"num\">\u00a702</span><span>Platform strategy</span></a>\n    <a href=\"#voice\"><span class=\"num\">\u00a703</span><span>Voice &amp; tone</span></a>\n    <a href=\"#visual\"><span class=\"num\">\u00a704</span><span>Visual system</span></a>\n    <a href=\"#palette\"><span class=\"num\">\u00a705</span><span>Palette</span></a>\n    <a href=\"#profiles\"><span class=\"num\">\u00a706</span><span>Profile setup</span></a>\n    <a href=\"#pillars\"><span class=\"num\">\u00a707</span><span>Content pillars</span></a>\n    <a href=\"#templates\"><span class=\"num\">\u00a708</span><span>Post templates</span></a>\n    <a href=\"#vertical\"><span class=\"num\">\u00a709</span><span>Vertical formats</span></a>\n    <a href=\"#captions\"><span class=\"num\">\u00a710</span><span>Captions &amp; hashtags</span></a>\n    <a href=\"#cadence\"><span class=\"num\">\u00a711</span><span>Cadence</span></a>\n    <a href=\"#guardrails\"><span class=\"num\">\u00a712</span><span>Guardrails</span></a>\n    <a href=\"#governance\"><span class=\"num\">\u00a713</span><span>Governance</span></a>\n\n    <div class=\"nav-label\">Companion files</div>\n    <a href=\"/\"><span class=\"num\">\u2197</span><span>Brand kit canvas</span></a>\n    <a href=\"/editor\"><span class=\"num\">\u2197</span><span>Post editor</span></a>\n\n    <div class=\"nav-foot\">\n      Maintained by the PrivexBot brand team.<br/>\n      Last reviewed: <strong style=\"color:var(--ink-700)\">May 2026</strong><br/>\n      Next review: <strong style=\"color:var(--ink-700)\">Aug 2026</strong><br/>\n      Source of truth: <a href=\"/\">brand kit</a>.\n    </div>\n  </aside>\n\n  <!-- ============= DOC ============= -->\n  <main class=\"doc\">\n    <div class=\"doc-inner\">\n\n      <!-- HERO -->\n      <header class=\"hero\">\n        <div class=\"eyebrow\"><span>The social playbook</span></div>\n        <h1>How PrivexBot shows up online.</h1>\n        <p class=\"deck\">A working document for everyone who posts, comments, replies, or makes a thumbnail on behalf of PrivexBot. Read it once. Refer to it often. Update it when reality drifts.</p>\n\n        <div class=\"hero-meta\">\n          <div>\n            <div class=\"k\">For</div>\n            <div class=\"v\">Marketing, founders, devrel, anyone with login access to a brand account.</div>\n          </div>\n          <div>\n            <div class=\"k\">Pairs with</div>\n            <div class=\"v\">The brand kit canvas and the post editor. Visual specs live there.</div>\n          </div>\n          <div>\n            <div class=\"k\">Owners</div>\n            <div class=\"v\">Brand lead reviews monthly. Founders own thesis &amp; voice changes.</div>\n          </div>\n          <div>\n            <div class=\"k\">Status</div>\n            <div class=\"v\">Live. Edits welcome via PR; major changes need brand-lead approval.</div>\n          </div>\n        </div>\n\n        <div class=\"toc-grid\">\n          <a href=\"#thesis\"><div class=\"num\">\u00a7 01</div><div class=\"ttl\">Thesis</div></a>\n          <a href=\"#strategy\"><div class=\"num\">\u00a7 02</div><div class=\"ttl\">Platform strategy</div></a>\n          <a href=\"#voice\"><div class=\"num\">\u00a7 03</div><div class=\"ttl\">Voice &amp; tone</div></a>\n          <a href=\"#visual\"><div class=\"num\">\u00a7 04</div><div class=\"ttl\">Visual system</div></a>\n          <a href=\"#palette\"><div class=\"num\">\u00a7 05</div><div class=\"ttl\">Palette</div></a>\n          <a href=\"#profiles\"><div class=\"num\">\u00a7 06</div><div class=\"ttl\">Profile setup</div></a>\n          <a href=\"#pillars\"><div class=\"num\">\u00a7 07</div><div class=\"ttl\">Content pillars</div></a>\n          <a href=\"#templates\"><div class=\"num\">\u00a7 08</div><div class=\"ttl\">Post templates</div></a>\n          <a href=\"#vertical\"><div class=\"num\">\u00a7 09</div><div class=\"ttl\">Vertical formats</div></a>\n          <a href=\"#captions\"><div class=\"num\">\u00a7 10</div><div class=\"ttl\">Captions &amp; hashtags</div></a>\n          <a href=\"#cadence\"><div class=\"num\">\u00a7 11</div><div class=\"ttl\">Cadence</div></a>\n          <a href=\"#guardrails\"><div class=\"num\">\u00a7 12</div><div class=\"ttl\">Guardrails &amp; governance</div></a>\n        </div>\n      </header>\n\n      <!-- ============= \u00a701 THESIS ============= -->\n      <section id=\"thesis\" class=\"section\">\n        <div class=\"section-num\">\u00a7 01 \u00b7 Thesis</div>\n        <h2 class=\"h-section\">Why PrivexBot is on social at all.</h2>\n        <p class=\"lede\">Most companies are on social because their competitors are. We're on social because the people who need us \u2014 privacy-burned engineers, compliance officers, regulated-industry product teams \u2014 don't know we exist yet. Our job is to find them.</p>\n\n        <h3 class=\"h-sub\">The problem we exist to solve</h3>\n        <p>Every AI tool in the market quietly assumes its users are willing to send their customers' data to three third parties. For consumer apps, that bargain is implicit and mostly accepted. For healthcare, fintech, legal, defense, government, education \u2014 the same bargain is illegal, unworkable, or career-ending. <strong>PrivexBot is the AI automation platform for teams that can't make that bargain.</strong></p>\n\n        <div class=\"pullquote\">\n          We replace trust with proof. Every inference is cryptographically attested, so you don't have to take our word for anything.\n          <span class=\"pullquote-attribution\">The PrivexBot pitch, in one sentence.</span>\n        </div>\n\n        <h3 class=\"h-sub\">What our social presence is for</h3>\n        <p>Three jobs, in priority order:</p>\n        <ol class=\"std\">\n          <li><strong>Educate.</strong> Most of our future customers don't know that \"private AI\" is technically possible at the inference layer. Posts that explain TEEs, attestation, and the actual privacy gap in mainstream tools do the heaviest lifting.</li>\n          <li><strong>Convert.</strong> Once someone understands the gap, we want them to try PrivexBot inside fifteen minutes. Every post path leads to <code>privexbot.com</code> with the friction stripped.</li>\n          <li><strong>Recruit.</strong> Engineers who care about this stuff are rare. The people who already do this work for free in OSS communities are who we want to hire. Build-in-public posts double as a recruiting funnel.</li>\n        </ol>\n\n        <h3 class=\"h-sub\">What our social presence is <em>not</em> for</h3>\n        <ul class=\"std\">\n          <li>Brand awareness for awareness's sake. We don't optimise for impressions or follower counts as ends.</li>\n          <li>Reacting to news cycles that don't intersect AI privacy. Stay in lane.</li>\n          <li>Customer support. Route to <code>support@privexbot.com</code>, always.</li>\n          <li>Internal celebrations. Birthdays, anniversaries, \"team off-site!\" content \u2014 these live on the careers page, not the brand timeline.</li>\n        </ul>\n\n        <div class=\"callout indigo\">\n          <div class=\"callout-eyebrow\">The thesis test</div>\n          <p>Before any post ships, ask: <em>does this educate, convert, or recruit?</em> If the honest answer is \"none of the above,\" it doesn't go out. Restraint is brand-building.</p>\n        </div>\n      </section>\n\n      <!-- ============= \u00a702 PLATFORM STRATEGY ============= -->\n      <section id=\"strategy\" class=\"section\">\n        <div class=\"section-num\">\u00a7 02 \u00b7 Platform strategy</div>\n        <h2 class=\"h-section\">Home, broadcast, placeholder.</h2>\n        <p class=\"lede\">We don't post everything everywhere. Each platform plays a defined role. Mis-cast a platform and you waste cycles on content that won't perform there.</p>\n\n        <h3 class=\"h-sub\">The three roles</h3>\n        <p><strong>Home</strong> platforms are where conversation happens. We invest most of our energy here: native posts, replies, threads, long-form. <strong>Broadcast</strong> platforms are publishing channels \u2014 we make a polished thing and put it up, but we don't expect a comment section. <strong>Placeholder</strong> platforms exist so we're not absent when someone searches; we maintain a credible profile and re-share the best of what's already published elsewhere.</p>\n\n        <table class=\"std\">\n          <thead>\n            <tr><th>Platform</th><th>Role</th><th>Primary audience</th><th>Primary format</th><th>Cadence</th></tr>\n          </thead>\n          <tbody>\n            <tr><td>X / Twitter</td><td><span class=\"tag t-home\">Home</span></td><td>Devs, founders, AI/privacy Twitter</td><td>Threads, replies, hot takes, build-in-public</td><td class=\"mono\">Daily, 1\u20133 posts</td></tr>\n            <tr><td>LinkedIn</td><td><span class=\"tag t-home\">Home</span></td><td>CTOs, compliance, enterprise buyers</td><td>Long-form posts, carousels, customer stories</td><td class=\"mono\">3\u00d7 per week</td></tr>\n            <tr><td>YouTube</td><td><span class=\"tag t-broadcast\">Broadcast</span></td><td>Devs looking to build something specific</td><td>Tutorials, deep dives, founder talks</td><td class=\"mono\">1\u00d7 per week (Tuesday)</td></tr>\n            <tr><td>Twitch</td><td><span class=\"tag t-broadcast\">Broadcast</span></td><td>Indie devs, learners, regulars</td><td>Live coding, Q&amp;A, paired builds</td><td class=\"mono\">1\u00d7 per week, scheduled</td></tr>\n            <tr><td>Instagram</td><td><span class=\"tag t-broadcast\">Broadcast</span></td><td>Indie hackers, SMB owners, founders</td><td>Carousels, Reels, quote cards</td><td class=\"mono\">3\u00d7 per week feed, 5\u00d7 stories</td></tr>\n            <tr><td>TikTok</td><td><span class=\"tag t-broadcast\">Broadcast</span></td><td>Younger devs, learners, viral discovery</td><td>Short explainers, hot takes, on-screen demos</td><td class=\"mono\">2\u20133\u00d7 per week</td></tr>\n            <tr><td>Facebook</td><td><span class=\"tag t-placeholder\">Placeholder</span></td><td>SMB owners in regulated industries</td><td>Repost LinkedIn + YouTube highlights</td><td class=\"mono\">1\u20132\u00d7 per week</td></tr>\n          </tbody>\n        </table>\n\n        <h3 class=\"h-sub\">Cross-posting rules</h3>\n        <ul class=\"std\">\n          <li><strong>Never cross-post raw.</strong> A LinkedIn post is not a tweet. A tweet is not an Instagram caption. Re-write the hook and trim or expand for the platform.</li>\n          <li><strong>Repurpose vertically.</strong> One YouTube tutorial \u2192 three TikTok cuts \u2192 one IG carousel \u2192 one LinkedIn explainer. Same idea, four shapes.</li>\n          <li><strong>Threads are platform-native.</strong> A 5-tweet thread on X becomes a single carousel on IG; never paste tweets into Instagram.</li>\n          <li><strong>Hashtags go where hashtags work.</strong> Heavy on IG/TikTok. Light on LinkedIn (1\u20133, max). Almost none on X.</li>\n        </ul>\n\n        <div class=\"callout\">\n          <div class=\"callout-eyebrow\">Channels we are intentionally not on</div>\n          <p><strong>Threads, Mastodon, Bluesky.</strong> The audiences we care about aren't there yet at meaningful scale. Revisit quarterly. <strong>Discord:</strong> we run a community server but that's a product surface, not a marketing channel \u2014 different playbook, different team.</p>\n        </div>\n      </section>\n\n      <!-- ============= \u00a703 VOICE & TONE ============= -->\n      <section id=\"voice\" class=\"section\">\n        <div class=\"section-num\">\u00a7 03 \u00b7 Voice &amp; tone</div>\n        <h2 class=\"h-section\">Plainspoken. Specific. Confident. Calm.</h2>\n        <p class=\"lede\">Our nearest neighbours in voice are Linear's release notes, Supabase's docs, and Vercel's product pages. We're a developer tool that's growing up into an enterprise platform. The voice has to age well into both rooms.</p>\n\n        <h3 class=\"h-sub\">The four attributes</h3>\n        <p><strong>Plainspoken.</strong> We use the simplest word that does the job. \"Encrypt,\" not \"leverage cryptographic primitives.\" \"Read your prompts,\" not \"process your inputs.\"</p>\n        <p><strong>Specific.</strong> \"Build a chatbot in fifteen minutes\" beats \"powerful AI for everyone.\" Numbers, named platforms, concrete tasks. Vague promises read as marketing; specifics read as truth.</p>\n        <p><strong>Confident.</strong> No hedging, no \"we think maybe,\" no \"could possibly help.\" We state. If we can't state it, we don't post it.</p>\n        <p><strong>Calm.</strong> Privacy is an anxious subject. The voice that earns trust here is the one that doesn't sound alarmed. We describe threats matter-of-factly and solutions equally so. No bold capitalisation. No exclamation points outside of jokes.</p>\n\n        <h3 class=\"h-sub\">Voice in practice</h3>\n\n        <h4 class=\"h-mini\">Saying what we do</h4>\n        <div class=\"voice-pair\">\n          <div class=\"yes\"><span class=\"lbl\">Voice \u2713</span>Build chatbots in fifteen minutes. Deploy to web, Discord, Slack, Telegram, WhatsApp.</div>\n          <div class=\"no\"><span class=\"lbl\">Off-brand</span>Unleash the power of AI! Build incredible chatbots in seconds and deploy them everywhere with one click \ud83d\ude80</div>\n        </div>\n\n        <h4 class=\"h-mini\">Talking about privacy</h4>\n        <div class=\"voice-pair\">\n          <div class=\"yes\"><span class=\"lbl\">Voice \u2713</span>Inference runs inside a Trusted Execution Environment. We can't read your prompts. Neither can your model host.</div>\n          <div class=\"no\"><span class=\"lbl\">Off-brand</span>\ud83d\udd12 100% Secure! Military-grade encryption protects your data. Your privacy is our #1 priority!</div>\n        </div>\n\n        <h4 class=\"h-mini\">Announcing a feature</h4>\n        <div class=\"voice-pair\">\n          <div class=\"yes\"><span class=\"lbl\">Voice \u2713</span>WhatsApp deploys. Now generally available. Connect your WhatsApp Business number to any agent.</div>\n          <div class=\"no\"><span class=\"lbl\">Off-brand</span>We're SO excited to announce our biggest update yet \ud83c\udf89\ud83c\udf89\ud83c\udf89 WhatsApp is HERE!!</div>\n        </div>\n\n        <h4 class=\"h-mini\">Handling an objection</h4>\n        <div class=\"voice-pair\">\n          <div class=\"yes\"><span class=\"lbl\">Voice \u2713</span>Fair question. We charge more than the major model APIs because we run inference inside hardware enclaves \u2014 that infrastructure costs us about 18% more. We pass it through, not 3\u00d7.</div>\n          <div class=\"no\"><span class=\"lbl\">Off-brand</span>Hey there! Great question \ud83d\ude0a Yes our pricing reflects the premium privacy you're getting. Hope this helps!</div>\n        </div>\n\n        <h3 class=\"h-sub\">Tone by surface</h3>\n        <p>Voice stays constant. Tone shifts.</p>\n        <table class=\"std\">\n          <thead><tr><th>Surface</th><th>Tone shift</th><th>Example opener</th></tr></thead>\n          <tbody>\n            <tr><td>X / Twitter</td><td>Sharper. Allowed to be punchy and a little contrarian.</td><td class=\"mono\">\"3 companies read your prompt before the model does. We fixed that.\"</td></tr>\n            <tr><td>LinkedIn</td><td>Considered, longer, more compliance-aware.</td><td class=\"mono\">\"A note for compliance teams evaluating AI vendors:\"</td></tr>\n            <tr><td>Instagram</td><td>Warmer, more visual-led, can explain like the reader is new.</td><td class=\"mono\">\"Here's what happens when you send a message to ChatGPT \u2192\"</td></tr>\n            <tr><td>YouTube</td><td>Tutorial-friendly, patient, lower jargon density.</td><td class=\"mono\">\"Today we're going to build a Discord bot that doesn't leak your data.\"</td></tr>\n            <tr><td>TikTok</td><td>Hook in first 1.5 seconds. Still serious, still calm.</td><td class=\"mono\">\"Your AI vendor isn't lying about privacy. They're being technically truthful.\"</td></tr>\n            <tr><td>Replies / DMs</td><td>Warmer, first-person, signed if it's a real human.</td><td class=\"mono\">\"Yes, that's a real limitation \u2014 we're working on it. \u2014 Sasha\"</td></tr>\n          </tbody>\n        </table>\n\n        <h3 class=\"h-sub\">Vocabulary</h3>\n        <div class=\"dod\">\n          <div class=\"do\">\n            <div class=\"head\">Prefer</div>\n            <ul>\n              <li><strong>Encrypted at rest, encrypted in use</strong> \u2014 accurate, specific</li>\n              <li><strong>Trusted Execution Environment (TEE)</strong> \u2014 name the tech</li>\n              <li><strong>Attestation</strong> \u2014 the proof we offer</li>\n              <li><strong>Chatflow</strong> \u2014 our visual builder noun</li>\n              <li><strong>Agent</strong> \u2014 when referring to a deployed bot</li>\n              <li><strong>Workspace</strong> \u2014 the user's home in the app</li>\n              <li><strong>Build, deploy, verify</strong> \u2014 three verbs we own</li>\n            </ul>\n          </div>\n          <div class=\"dont\">\n            <div class=\"head\">Avoid</div>\n            <ul>\n              <li><strong>\"Military-grade\"</strong> \u2014 meaningless, makes us sound like a VPN ad</li>\n              <li><strong>\"AI-powered\"</strong> \u2014 true of everything; says nothing</li>\n              <li><strong>\"Revolutionary,\" \"game-changing,\" \"next-gen\"</strong> \u2014 empty</li>\n              <li><strong>\"Solutions\"</strong> \u2014 we make a product, not solutions</li>\n              <li><strong>\"Leverage,\" \"utilise,\" \"operationalise\"</strong> \u2014 say \"use\"</li>\n              <li><strong>\"Best-in-class\"</strong> \u2014 let the work prove that</li>\n              <li><strong>\"Powered by AI\"</strong> \u2014 what isn't, in 2026</li>\n            </ul>\n          </div>\n        </div>\n\n        <h3 class=\"h-sub\">Sentence case, always</h3>\n        <p>Titles, headlines, CTAs, button labels \u2014 all sentence case. <code>Read the changelog</code>, not <code>Read The Changelog</code>. Exception: proper nouns and the brand name itself (PRIVEXBOT in the wordmark; PrivexBot in running text).</p>\n\n        <h3 class=\"h-sub\">Em-dashes, semicolons, oxford commas</h3>\n        <p>Em-dash (\u2014) is welcome \u2014 it's a workhorse of our rhythm. Oxford comma always. Semicolons used sparingly, when two clauses are genuinely independent but related. Don't fear the period; short sentences land harder.</p>\n      </section>\n\n      <!-- ============= \u00a704 VISUAL SYSTEM ============= -->\n      <section id=\"visual\" class=\"section\">\n        <div class=\"section-num\">\u00a7 04 \u00b7 Visual system</div>\n        <h2 class=\"h-section\">Four lanes. One mark. Lots of whitespace.</h2>\n        <p class=\"lede\">Visual variety on social is good; visual chaos is not. We solve this by committing to four visual lanes. Every post lives in exactly one. Cross-lane combinations are how decks start looking like Canva freebies.</p>\n\n        <h3 class=\"h-sub\">The four lanes</h3>\n\n        <h4 class=\"h-mini\">Mono (default)</h4>\n        <p>White surface, ink-950 typography, signal-500 accents. The everyday lane. Use for tutorials, changelogs, build-in-public, comparisons. ~50% of feed posts live here.</p>\n\n        <h4 class=\"h-mini\">Dark</h4>\n        <p>Ink-950 surface, white type, signal indigo radial glows, sage attest highlights. The \"infrastructure\" lane \u2014 feels like a devtool homepage. Use for privacy/TEE explainers, launches, hot takes, anything that needs gravitas. ~30% of posts.</p>\n\n        <h4 class=\"h-mini\">Light</h4>\n        <p>Signal-50 or ink-25 surface, ink typography, signal-500 dominant. Friendlier SaaS feel. Use for stats, build-in-public, customer outcomes, CTAs. ~15% of posts.</p>\n\n        <h4 class=\"h-mini\">Editorial</h4>\n        <p>White surface with a dot grid texture, big display type, signal indigo accents, optional pull-quote treatments. Use for founder essays, manifestos, customer quotes, industry takes. ~5% of posts \u2014 rare on purpose.</p>\n\n        <div class=\"callout\">\n          <div class=\"callout-eyebrow\">Rule of one</div>\n          <p>One lane per post. One accent color per post. One display headline per post. If a layout feels weak, the fix is bigger type or more whitespace \u2014 not more decoration.</p>\n        </div>\n\n        <h3 class=\"h-sub\">The logo</h3>\n        <p>One mark, five colorways. The shape is fixed and never modified. Variants are colour-only:</p>\n        <ul class=\"std\">\n          <li><strong>Indigo</strong> on white \u2014 the default lockup</li>\n          <li><strong>Black</strong> on white \u2014 when colour fidelity isn't guaranteed (print, partner decks)</li>\n          <li><strong>White</strong> on dark \u2014 dark lane, video thumbnails, dark-mode profiles</li>\n          <li><strong>Indigo light</strong> on signal-900 \u2014 high-contrast hero moments</li>\n          <li><strong>Sage</strong> \u2014 reserved for security-themed assets only; never decorative</li>\n        </ul>\n\n        <h4 class=\"h-mini\">Clearspace</h4>\n        <p>Minimum clearspace around the mark = the height of the \"P\" cap. Never crop into the mark. Never rotate, skew, stretch, or layer effects on it. Never put it inside another shape that competes for attention.</p>\n\n        <h4 class=\"h-mini\">Wordmark</h4>\n        <p>Wordmark is Inter Tight 800 in <code>PRIVEXBOT</code> capitals with <code>0.08em</code> tracking. Always paired with the mark; never set on its own at large sizes. For body running text use sentence-case <code>PrivexBot</code>.</p>\n\n        <h3 class=\"h-sub\">Typography</h3>\n        <table class=\"std\">\n          <thead><tr><th>Family</th><th>Use</th><th>Sizes</th></tr></thead>\n          <tbody>\n            <tr><td>Inter Tight</td><td>Display headlines, hero type, wordmark</td><td class=\"mono\">48\u2013144px, weight 700</td></tr>\n            <tr><td>Inter</td><td>Body, UI, captions, labels</td><td class=\"mono\">14\u201322px, weight 400/500/600</td></tr>\n            <tr><td>JetBrains Mono</td><td>Code, API endpoints, eyebrows, metadata, technical tags</td><td class=\"mono\">11\u201316px, weight 400/500/600</td></tr>\n          </tbody>\n        </table>\n\n        <h3 class=\"h-sub\">Iconography</h3>\n        <p>Use the Lucide icon set (1.5px stroke, currentColor). Never mix icon sets in one post. Never use a multi-colour icon. Never use emoji as an icon substitute \u2014 emoji is allowed sparingly as content (jokes, IG bio bullets, casual replies) but never as an interface element on a post template.</p>\n\n        <h3 class=\"h-sub\">Photography &amp; imagery</h3>\n        <p>We don't use stock photography. Ever. Posts that need a visual element use one of three approaches:</p>\n        <ol class=\"std\">\n          <li><strong>Type-led layouts</strong> \u2014 let the headline do the work (most posts)</li>\n          <li><strong>Geometric / abstract compositions</strong> \u2014 angled shapes, dot grids, radial gradients in brand colours</li>\n          <li><strong>Real product screenshots</strong> \u2014 when we can show actual chatflow UI, attestation receipts, or the visual builder</li>\n        </ol>\n        <p>For customer/use-case posts that benefit from a face: a real photo, monochrome with a signal-500 duotone treatment. Never generic \"diverse team smiling at laptop\" stock.</p>\n\n        <div class=\"callout attest\">\n          <div class=\"callout-eyebrow\">\u2713 The screenshot test</div>\n          <p>Look at the post next to ten unrelated posts in the platform's native feed. If you can identify it as ours without seeing the avatar, the visual system is doing its job. If it could be Notion, Linear, Vercel, or a generic SaaS \u2014 pull it and start over.</p>\n        </div>\n      </section>\n\n      <!-- ============= \u00a705 PALETTE ============= -->\n      <section id=\"palette\" class=\"section\">\n        <div class=\"section-num\">\u00a7 05 \u00b7 Palette</div>\n        <h2 class=\"h-section\">Three roles. No exceptions.</h2>\n        <p class=\"lede\">Indigo for trust. Sage for verified state. Ink for everything else. Anything outside these three roles is an off-brand colour and won't ship.</p>\n\n        <h3 class=\"h-sub\">Brand \u00b7 signal indigo</h3>\n        <p>The trust anchor. Used to draw the eye to one \u2014 exactly one \u2014 element per composition: the CTA, the headline highlight, an accent rule, the brand mark. The 500 weight is canonical; the lighter tints (50, 100) provide quiet surface fills.</p>\n\n        <div class=\"palette\">\n          <div class=\"sw\"><div class=\"chip\" style=\"background:#131941\"></div><div class=\"meta\"><div class=\"name\">signal-900</div><div class=\"hex\">#131941</div></div></div>\n          <div class=\"sw\"><div class=\"chip\" style=\"background:#1A2256\"></div><div class=\"meta\"><div class=\"name\">signal-800</div><div class=\"hex\">#1A2256</div></div></div>\n          <div class=\"sw\"><div class=\"chip\" style=\"background:#212B6F\"></div><div class=\"meta\"><div class=\"name\">signal-700</div><div class=\"hex\">#212B6F</div></div></div>\n          <div class=\"sw\"><div class=\"chip\" style=\"background:#3947A8\"></div><div class=\"meta\"><div class=\"name\">signal-500 \u2605</div><div class=\"hex\">#3947A8</div></div></div>\n          <div class=\"sw\"><div class=\"chip\" style=\"background:#5866C2\"></div><div class=\"meta\"><div class=\"name\">signal-400</div><div class=\"hex\">#5866C2</div></div></div>\n          <div class=\"sw\"><div class=\"chip\" style=\"background:#8892D8\"></div><div class=\"meta\"><div class=\"name\">signal-300</div><div class=\"hex\">#8892D8</div></div></div>\n          <div class=\"sw\"><div class=\"chip\" style=\"background:#D9DDF4\"></div><div class=\"meta\"><div class=\"name\">signal-100</div><div class=\"hex\">#D9DDF4</div></div></div>\n        </div>\n\n        <h3 class=\"h-sub\">Attest \u00b7 sage</h3>\n        <p>Reserved. Sage signals \"verified, encrypted, attested, running.\" It appears on TEE badges, attestation receipts, success states, security-themed assets \u2014 never as decoration. When you reach for sage, ask: is this post literally about something being verified? If no, use indigo.</p>\n\n        <div class=\"palette\" style=\"grid-template-columns:repeat(3,1fr); max-width:340px\">\n          <div class=\"sw\"><div class=\"chip\" style=\"background:#285A3D\"></div><div class=\"meta\"><div class=\"name\">attest-700</div><div class=\"hex\">#285A3D</div></div></div>\n          <div class=\"sw\"><div class=\"chip\" style=\"background:#3E8A5E\"></div><div class=\"meta\"><div class=\"name\">attest-500 \u2605</div><div class=\"hex\">#3E8A5E</div></div></div>\n          <div class=\"sw\"><div class=\"chip\" style=\"background:#DCEBE1\"></div><div class=\"meta\"><div class=\"name\">attest-100</div><div class=\"hex\">#DCEBE1</div></div></div>\n        </div>\n\n        <h3 class=\"h-sub\">Ink \u00b7 neutrals</h3>\n        <p>Slightly cool greys \u2014 the workhorse. Backgrounds, body text, borders, dividers. <code>ink-950</code> is our canonical dark surface; <code>ink-25</code> our canonical light surface.</p>\n\n        <div class=\"palette\">\n          <div class=\"sw\"><div class=\"chip\" style=\"background:#0A0C10\"></div><div class=\"meta\"><div class=\"name\">ink-950</div><div class=\"hex\">#0A0C10</div></div></div>\n          <div class=\"sw\"><div class=\"chip\" style=\"background:#161A22\"></div><div class=\"meta\"><div class=\"name\">ink-800</div><div class=\"hex\">#161A22</div></div></div>\n          <div class=\"sw\"><div class=\"chip\" style=\"background:#3A4051\"></div><div class=\"meta\"><div class=\"name\">ink-500</div><div class=\"hex\">#3A4051</div></div></div>\n          <div class=\"sw\"><div class=\"chip\" style=\"background:#858C9D\"></div><div class=\"meta\"><div class=\"name\">ink-300</div><div class=\"hex\">#858C9D</div></div></div>\n          <div class=\"sw\"><div class=\"chip\" style=\"background:#D9DCE3\"></div><div class=\"meta\"><div class=\"name\">ink-100</div><div class=\"hex\">#D9DCE3</div></div></div>\n          <div class=\"sw\"><div class=\"chip\" style=\"background:#F9FAFB; border:1px solid var(--ink-100)\"></div><div class=\"meta\"><div class=\"name\">ink-25</div><div class=\"hex\">#F9FAFB</div></div></div>\n          <div class=\"sw\"><div class=\"chip\" style=\"background:#FFFFFF; border:1px solid var(--ink-100)\"></div><div class=\"meta\"><div class=\"name\">ink-0</div><div class=\"hex\">#FFFFFF</div></div></div>\n        </div>\n\n        <h3 class=\"h-sub\">Forbidden combinations</h3>\n        <div class=\"dod\">\n          <div class=\"do\">\n            <div class=\"head\">Approved</div>\n            <ul>\n              <li>Ink-950 surface + signal-300/400 accents (Dark lane)</li>\n              <li>Ink-0 surface + signal-500 accents (Mono lane)</li>\n              <li>Signal-50 surface + signal-500/700 accents (Light lane)</li>\n              <li>Signal-500 surface + ink-0 type (CTA / hero buttons)</li>\n              <li>Any surface + attest-500 (security-themed only)</li>\n            </ul>\n          </div>\n          <div class=\"dont\">\n            <div class=\"head\">Never ship</div>\n            <ul>\n              <li>Signal + attest as equal accents in one post (sage is reserved, not co-equal)</li>\n              <li>Gradients across more than two brand colours</li>\n              <li>Warn/danger as decoration (red is for crisis only)</li>\n              <li>Pure black (#000) \u2014 always use ink-950 for the slight warmth</li>\n              <li>White type on coloured backgrounds without a contrast check; always WCAG AA</li>\n              <li>Off-system colours introduced for \"fun\" \u2014 there is no off-system fun</li>\n            </ul>\n          </div>\n        </div>\n\n        <h3 class=\"h-sub\">Accessibility</h3>\n        <p>Body text on any surface must clear WCAG AA contrast (4.5:1). Display type \u2265 24px must clear 3:1. <code>ink-300</code> on <code>ink-25</code> fails \u2014 never use it for body. <code>signal-300</code> on <code>ink-950</code> passes \u2014 that's the standard dark-lane accent pair. When in doubt, run the post through a contrast checker before publishing.</p>\n      </section>\n\n      <!-- ============= \u00a706 PROFILE SETUP ============= -->\n      <section id=\"profiles\" class=\"section\">\n        <div class=\"section-num\">\u00a7 06 \u00b7 Profile setup</div>\n        <h2 class=\"h-section\">Show up the same way everywhere.</h2>\n        <p class=\"lede\">A consistent profile is the cheapest brand investment we make. A new visitor on any platform should instantly recognise us as the same company that posted the thing that brought them there. Copy-paste these.</p>\n\n        <h3 class=\"h-sub\">The universal handle</h3>\n        <p>Handle is <code>@privexbot</code> everywhere it's available. If taken, fall back in this order: <code>@privexbot_ai</code>, <code>@privexbotapp</code>, <code>@privexbot_io</code>. Display name is always <code>PrivexBot</code> (sentence case, no separator).</p>\n\n        <h3 class=\"h-sub\">Per-platform setup checklist</h3>\n\n        <div class=\"checklist\">\n          <div>\n            <h4><span class=\"icn\">X</span> X / Twitter</h4>\n            <ul>\n              <li class=\"done\">Avatar: <code>av-indigo</code> 400\u00d7400 (indigo bg, white mark)</li>\n              <li class=\"done\">Header: X header banner (1500\u00d7500, dark lane)</li>\n              <li class=\"done\">Display name: <code>PrivexBot</code></li>\n              <li class=\"done\">Bio (160 chars max): see Bio reference card</li>\n              <li class=\"done\">Location: <code>Encrypted, distributed</code></li>\n              <li class=\"done\">Website: <code>privexbot.com</code></li>\n              <li class=\"done\">Pinned post: launch thread or current campaign</li>\n              <li class=\"done\">Premium verification enabled (blue check)</li>\n            </ul>\n          </div>\n          <div>\n            <h4><span class=\"icn\">in</span> LinkedIn</h4>\n            <ul>\n              <li class=\"done\">Company logo: <code>av-indigo</code> 400\u00d7400</li>\n              <li class=\"done\">Cover image: LinkedIn cover (1584\u00d7396, light lane)</li>\n              <li class=\"done\">Tagline (120 chars): see Bio reference</li>\n              <li class=\"done\">About section: full long-form bio</li>\n              <li class=\"done\">Industry: <code>Software Development</code></li>\n              <li class=\"done\">Company size: actual (11\u201350)</li>\n              <li class=\"done\">Specialties: privacy, AI, RAG, chatbots, TEE</li>\n              <li class=\"done\">Featured posts: pin 3 highest-performing</li>\n            </ul>\n          </div>\n          <div>\n            <h4><span class=\"icn\">IG</span> Instagram</h4>\n            <ul>\n              <li class=\"done\">Avatar: <code>av-ink</code> 400\u00d7400 (ink, dot grid)</li>\n              <li class=\"done\">Bio: 4-line emoji bullets (see Bio reference)</li>\n              <li class=\"done\">Link in bio: <code>privexbot.com</code> via Linktree or native link sticker</li>\n              <li class=\"done\">Category: <code>Software company</code></li>\n              <li class=\"done\">Highlights: Privacy \u00b7 Tutorials \u00b7 Customers \u00b7 Changelog \u00b7 Team (5 reels covers in brand colours)</li>\n              <li class=\"done\">Contact info: link out (email NOT public \u2014 DM only)</li>\n            </ul>\n          </div>\n          <div>\n            <h4><span class=\"icn\">YT</span> YouTube</h4>\n            <ul>\n              <li class=\"done\">Avatar: <code>av-ink</code> 400\u00d7400</li>\n              <li class=\"done\">Channel art: YouTube banner (2560\u00d71440, safe area centered)</li>\n              <li class=\"done\">Handle: <code>@privexbot</code></li>\n              <li class=\"done\">About: long bio + 5 links (site, docs, X, GitHub, Discord)</li>\n              <li class=\"done\">Channel trailer for non-subs: 60s explainer</li>\n              <li class=\"done\">Featured video for subs: latest tutorial</li>\n              <li class=\"done\">Sections: Tutorials \u00b7 Live builds \u00b7 Privacy deep dives \u00b7 Changelog</li>\n            </ul>\n          </div>\n          <div>\n            <h4><span class=\"icn\">TT</span> TikTok</h4>\n            <ul>\n              <li class=\"done\">Avatar: <code>av-indigo</code> 400\u00d7400</li>\n              <li class=\"done\">Display name: <code>PrivexBot \u00b7 Privacy AI</code></li>\n              <li class=\"done\">Bio: 4-line emoji bullets (80 char limit \u2014 tighter than IG)</li>\n              <li class=\"done\">Link in bio: <code>privexbot.com</code></li>\n              <li class=\"done\">Category: <code>Apps</code> or <code>Technology</code></li>\n              <li class=\"done\">Business account toggled on (analytics)</li>\n            </ul>\n          </div>\n          <div>\n            <h4><span class=\"icn\">Tw</span> Twitch</h4>\n            <ul>\n              <li class=\"done\">Avatar: <code>av-indigo</code> 400\u00d7400</li>\n              <li class=\"done\">Banner: Twitch banner (1200\u00d7480, dark lane)</li>\n              <li class=\"done\">Display name: <code>PrivexBot</code></li>\n              <li class=\"done\">Bio / channel description (300 chars)</li>\n              <li class=\"done\">Schedule: Tuesdays 14:00 UTC published</li>\n              <li class=\"done\">Panels: About \u00b7 Schedule \u00b7 Stack \u00b7 Discord \u00b7 Sponsor (PrivexBot.com)</li>\n              <li class=\"done\">Overlays: dark lane, brand mark bottom-right</li>\n            </ul>\n          </div>\n          <div>\n            <h4><span class=\"icn\">f</span> Facebook</h4>\n            <ul>\n              <li class=\"done\">Page profile pic: <code>av-indigo</code> 400\u00d7400</li>\n              <li class=\"done\">Cover: Facebook cover (1640\u00d7856, light lane)</li>\n              <li class=\"done\">Page name: <code>PrivexBot</code></li>\n              <li class=\"done\">Username: <code>@privexbot</code></li>\n              <li class=\"done\">Category: <code>Software company</code></li>\n              <li class=\"done\">About \u2192 Story: long-form mission</li>\n              <li class=\"done\">Call-to-action button: <code>Sign Up</code> \u2192 privexbot.com</li>\n            </ul>\n          </div>\n          <div>\n            <h4><span class=\"icn\">GH</span> GitHub (org)</h4>\n            <ul>\n              <li class=\"done\">Org avatar: <code>av-indigo</code> 400\u00d7400</li>\n              <li class=\"done\">Description: short tagline</li>\n              <li class=\"done\">URL: <code>privexbot.com</code></li>\n              <li class=\"done\">README in <code>.github</code> repo: pinned hero</li>\n              <li class=\"done\">Pinned repos: SDK, examples, awesome-privex, attestation-cli</li>\n              <li class=\"done\">Twitter linked</li>\n            </ul>\n          </div>\n        </div>\n\n        <p>Full visual mockups of each profile (showing exactly how the avatar + banner + bio compose in-platform) live in the <a href=\"index.html#profiles\" class=\"inline\">brand kit canvas \u2192 Profile setups section</a>.</p>\n      </section>\n\n      <!-- ============= \u00a707 CONTENT PILLARS ============= -->\n      <section id=\"pillars\" class=\"section\">\n        <div class=\"section-num\">\u00a7 07 \u00b7 Content pillars</div>\n        <h2 class=\"h-section\">Six pillars. Every post slots into one.</h2>\n        <p class=\"lede\">If you can't identify the pillar in five seconds, the post needs sharpening. The pillars also drive cadence \u2014 each one gets a target percentage of monthly output.</p>\n\n        <table class=\"std\">\n          <thead><tr><th>Pillar</th><th>Goal</th><th>Share</th><th>Templates</th></tr></thead>\n          <tbody>\n            <tr><td>Privacy &amp; TEE explainers</td><td>Educate the market on the privacy gap</td><td class=\"mono\">25%</td><td>Privacy post, Manifesto, Receipt, FAQ, Hot take</td></tr>\n            <tr><td>Product feature drops</td><td>Show what's new; signal velocity</td><td class=\"mono\">20%</td><td>Feature announcement, Launch post, Blog promo</td></tr>\n            <tr><td>Tutorials &amp; how-tos</td><td>Help developers build something specific</td><td class=\"mono\">20%</td><td>Tip post, Tutorial story, YouTube thumbnail</td></tr>\n            <tr><td>Use cases &amp; customers</td><td>Show real outcomes in real industries</td><td class=\"mono\">15%</td><td>Use case post, Customer quote, Community spotlight</td></tr>\n            <tr><td>Industry POV &amp; hot takes</td><td>Stake positions; participate in the conversation</td><td class=\"mono\">10%</td><td>Hot take, Manifesto, Comparison</td></tr>\n            <tr><td>Build-in-public</td><td>Recruit, build community, show humanity</td><td class=\"mono\">10%</td><td>Build post, Stat card, Meme, Behind-the-scenes</td></tr>\n          </tbody>\n        </table>\n\n        <h3 class=\"h-sub\">Pillar deep dives</h3>\n\n        <h4 class=\"h-mini\">Privacy &amp; TEE explainers</h4>\n        <p>The flagship pillar. Posts explain what a Trusted Execution Environment is, what attestation is, what the actual privacy gap looks like in mainstream tools, what threat models PrivexBot defends against. Always concrete \u2014 never abstract \"privacy matters!\" content.</p>\n        <p><strong>Sample hooks:</strong></p>\n        <ul class=\"std\">\n          <li>\"Three companies read your prompt before the model does. Here's the receipt that proves we don't.\"</li>\n          <li>\"What 'private' actually means at the inference layer.\"</li>\n          <li>\"You can't promise privacy. You can prove it. Here's how.\"</li>\n        </ul>\n\n        <h4 class=\"h-mini\">Product feature drops</h4>\n        <p>New nodes in the chatflow builder. New deploy targets. New integrations. Pricing changes. Roadmap unlocks. Keep it factual; let the screenshot or short demo do the persuading.</p>\n        <p><strong>Sample hooks:</strong></p>\n        <ul class=\"std\">\n          <li>\"WhatsApp deploys. Now generally available.\"</li>\n          <li>\"Visual chatflow builder v2. 14 new nodes. Inline run inspector.\"</li>\n          <li>\"Self-hostable Llama 3 70B. Same workspace. Same encryption.\"</li>\n        </ul>\n\n        <h4 class=\"h-mini\">Tutorials &amp; how-tos</h4>\n        <p>Step-by-step builds. The format that converts best \u2014 viewer sees they could ship the same thing in 15 minutes. Always end on a deployable artefact.</p>\n        <p><strong>Sample hooks:</strong></p>\n        <ul class=\"std\">\n          <li>\"Build a Discord support bot in 14 minutes.\"</li>\n          <li>\"Add a 200-page PDF to your chatbot's brain.\"</li>\n          <li>\"Connect your knowledge base to Slack \u2014 no API keys involved.\"</li>\n        </ul>\n\n        <h4 class=\"h-mini\">Use cases &amp; customers</h4>\n        <p>Real stories from real teams. Healthcare, legal, fintech, government, education \u2014 regulated industries are our home turf. Names where permitted; pseudonyms (\"a 200-bed hospital in the Midwest\") where not. Always include a quote and a metric.</p>\n\n        <h4 class=\"h-mini\">Industry POV &amp; hot takes</h4>\n        <p>Positions on AI privacy, vendor opacity, the difference between \"compliant\" and \"secure.\" Allowed to be sharp \u2014 never punching down at named competitors, always punching at industry practices.</p>\n\n        <h4 class=\"h-mini\">Build-in-public</h4>\n        <p>Engineering postmortems, traffic milestones, hiring stories, design process. Build credibility with the engineering audience that ends up either using or building PrivexBot.</p>\n      </section>\n\n      <!-- ============= \u00a708 POST TEMPLATES ============= -->\n      <section id=\"templates\" class=\"section\">\n        <div class=\"section-num\">\u00a7 08 \u00b7 Post templates</div>\n        <h2 class=\"h-section\">Don't design from scratch. Use the kit.</h2>\n        <p class=\"lede\">There are 19 templates in the brand kit. Each maps to specific pillars and platforms. Open the editor, pick the template, swap the copy, export. If you're hand-designing a post in Figma, you're probably doing it wrong.</p>\n\n        <h3 class=\"h-sub\">Template index</h3>\n        <table class=\"std\">\n          <thead><tr><th>Template</th><th>Lane</th><th>Best for</th><th>Where</th></tr></thead>\n          <tbody>\n            <tr><td>Privacy / TEE post</td><td>Dark</td><td>Privacy explainers, manifesto-adjacent</td><td>X, LI, IG</td></tr>\n            <tr><td>Feature announcement</td><td>Mono</td><td>Product launches, changelog drops</td><td>All feeds</td></tr>\n            <tr><td>Customer quote</td><td>Editorial</td><td>Customer stories, testimonials</td><td>LI, IG, X</td></tr>\n            <tr><td>Big stat card</td><td>Light</td><td>Build-in-public metrics, benchmarks</td><td>All feeds</td></tr>\n            <tr><td>Tutorial / tip</td><td>Mono</td><td>3-step how-tos, mini tutorials</td><td>IG, LI carousel</td></tr>\n            <tr><td>Launch / milestone</td><td>Dark</td><td>Launch week, major releases</td><td>X, LI, IG</td></tr>\n            <tr><td>Build-in-public</td><td>Light</td><td>Engineering wins, before/after</td><td>X, LI</td></tr>\n            <tr><td>Hot take</td><td>Editorial</td><td>Industry POV, contrarian positions</td><td>X, LI</td></tr>\n            <tr><td>Meme</td><td>Mono</td><td>Friday energy, observational humour</td><td>X, IG</td></tr>\n            <tr><td>Blog promo</td><td>Dark</td><td>Engineering blog, long-form essays</td><td>X, LI</td></tr>\n            <tr><td>Why we built it</td><td>Editorial</td><td>Founder story, mission</td><td>LI, IG</td></tr>\n            <tr><td>Manifesto</td><td>Dark</td><td>Hero statements, campaign covers</td><td>All feeds</td></tr>\n            <tr><td>Problem / solution</td><td>Mono</td><td>Quick \"before/after\" framing</td><td>LI, IG</td></tr>\n            <tr><td>Did you know (FAQ)</td><td>Light</td><td>Educational, single-stat answers</td><td>IG, TikTok cover</td></tr>\n            <tr><td>Comparison</td><td>Mono</td><td>Vs alternatives, feature matrices</td><td>LI, X</td></tr>\n            <tr><td>Use case</td><td>Dark</td><td>Industry-specific stories</td><td>LI</td></tr>\n            <tr><td>Attestation receipt</td><td>Dark</td><td>Proof posts, technical credibility</td><td>X, LI</td></tr>\n            <tr><td>Community spotlight</td><td>Mono</td><td>Featuring bots built on PrivexBot</td><td>All feeds</td></tr>\n            <tr><td>Sign-up CTA</td><td>Light</td><td>Campaign closers, end-of-thread CTAs</td><td>All feeds</td></tr>\n          </tbody>\n        </table>\n\n        <div class=\"callout indigo\">\n          <div class=\"callout-eyebrow\">\u2192 Live preview</div>\n          <p>Every template above is rendered in <a href=\"index.html#square\" class=\"inline\">the brand kit canvas</a>. To edit copy and export PNGs at native size, use <a href=\"/editor\" class=\"inline\">the post editor</a>. To request a new template, open a PR on the kit \u2014 don't invent one in Figma.</p>\n        </div>\n      </section>\n\n      <!-- ============= \u00a709 VERTICAL FORMATS ============= -->\n      <section id=\"vertical\" class=\"section\">\n        <div class=\"section-num\">\u00a7 09 \u00b7 Vertical formats</div>\n        <h2 class=\"h-section\">Stories, Reels, Shorts, TikTok.</h2>\n        <p class=\"lede\">Vertical surfaces have their own rules. Hook in 1.5 seconds. Single idea per video. On-screen text always \u2014 most viewers are scrolling without audio.</p>\n\n        <h3 class=\"h-sub\">Format specs</h3>\n        <table class=\"std\">\n          <thead><tr><th>Format</th><th>Aspect</th><th>Native length</th><th>Loop?</th><th>Captions burned in?</th></tr></thead>\n          <tbody>\n            <tr><td>Instagram Story</td><td class=\"mono\">1080\u00d71920</td><td class=\"mono\">15s</td><td>No</td><td>Yes</td></tr>\n            <tr><td>Instagram Reel</td><td class=\"mono\">1080\u00d71920</td><td class=\"mono\">15\u201360s sweet spot, 90s max</td><td>Yes</td><td>Yes</td></tr>\n            <tr><td>TikTok</td><td class=\"mono\">1080\u00d71920</td><td class=\"mono\">21\u201334s sweet spot</td><td>Yes</td><td>Yes</td></tr>\n            <tr><td>YouTube Short</td><td class=\"mono\">1080\u00d71920</td><td class=\"mono\">\u2264 60s</td><td>Yes</td><td>Yes</td></tr>\n          </tbody>\n        </table>\n\n        <h3 class=\"h-sub\">Vertical hook structure</h3>\n        <p>Every vertical video follows the same five-beat structure:</p>\n        <ol class=\"std\">\n          <li><strong>Hook (0\u20131.5s)</strong> \u2014 the question, claim, or visual pattern interrupt that makes someone stop scrolling</li>\n          <li><strong>Context (1.5\u20135s)</strong> \u2014 what we're about to show or claim</li>\n          <li><strong>Body (5\u201325s)</strong> \u2014 the actual content: demo, explanation, stat, takeaway</li>\n          <li><strong>Payoff (last 3\u20135s)</strong> \u2014 the insight, the answer, the \"so what\"</li>\n          <li><strong>CTA (final 2s, or in caption)</strong> \u2014 what to do next; for short formats often just a logo flash</li>\n        </ol>\n\n        <h3 class=\"h-sub\">On-screen text rules</h3>\n        <ul class=\"std\">\n          <li><strong>Inter Tight 700</strong>, 48\u201380pt for hooks; 32\u201348pt for body. Never smaller than 28pt \u2014 TikTok compresses tiny text into mush.</li>\n          <li><strong>White on ink-950 backdrop</strong> for maximum legibility. If overlaying live footage, drop a 70% opacity ink-950 plate behind the text.</li>\n          <li><strong>One sentence at a time.</strong> Each thought gets its own card. No paragraphs on a screen.</li>\n          <li><strong>Caption everything.</strong> Use auto-captions then proofread. Spell PrivexBot correctly every time (auto-caption defaults to \"Privacy Bot\").</li>\n          <li><strong>No watermarks from external editors.</strong> CapCut watermarks specifically \u2014 strip them. Sponsored watermarks (TikTok's built-in) are fine.</li>\n        </ul>\n\n        <h3 class=\"h-sub\">Story / reel cover stickers</h3>\n        <p>Five highlight cover designs live in the kit \u2014 Privacy, Tutorials, Customers, Changelog, Team. Use those exact covers for Instagram highlights. Don't create new ones; if a sixth category is needed, add it to the kit first.</p>\n\n        <h3 class=\"h-sub\">Audio</h3>\n        <ul class=\"std\">\n          <li><strong>Original audio preferred.</strong> Voiceovers, ambient room tone, keystroke clicks. It performs better in algorithm signals than trending music.</li>\n          <li><strong>Trending audio is allowed</strong> for memes and lighthearted posts only. Never use trending audio under a privacy/TEE explainer \u2014 tonally wrong.</li>\n          <li><strong>Music ducked under voiceover.</strong> If music plays during talk, drop it to -18db.</li>\n        </ul>\n      </section>\n\n      <!-- ============= \u00a710 CAPTIONS & HASHTAGS ============= -->\n      <section id=\"captions\" class=\"section\">\n        <div class=\"section-num\">\u00a7 10 \u00b7 Captions &amp; hashtags</div>\n        <h2 class=\"h-section\">The post is the image. The caption is the conversation.</h2>\n        <p class=\"lede\">Most engagement happens because the caption gave someone a reason to comment. Hashtags are discoverability infrastructure, not decoration.</p>\n\n        <h3 class=\"h-sub\">The universal caption formula</h3>\n        <div class=\"formula\">\n          <div class=\"label\">Caption template (any platform)</div>\n          <div class=\"lines\">\n            <div><span class=\"c\">// 1.</span> <span class=\"k\">Hook</span>     <span class=\"v\">\u2192 one sentence that earns the next sentence</span></div>\n            <div><span class=\"c\">// 2.</span> <span class=\"k\">Context</span>  <span class=\"v\">\u2192 what we did / saw / built / believe</span></div>\n            <div><span class=\"c\">// 3.</span> <span class=\"k\">Body</span>     <span class=\"v\">\u2192 the meat: explanation, story, list, link</span></div>\n            <div><span class=\"c\">// 4.</span> <span class=\"k\">CTA</span>      <span class=\"v\">\u2192 what to do (try, read, reply, share)</span></div>\n            <div><span class=\"c\">// 5.</span> <span class=\"k\">Hashtags</span> <span class=\"v\">\u2192 per-platform set, last</span></div>\n          </div>\n        </div>\n\n        <h3 class=\"h-sub\">Per-platform caption length</h3>\n        <table class=\"std\">\n          <thead><tr><th>Platform</th><th>Ideal length</th><th>Max</th><th>Notes</th></tr></thead>\n          <tbody>\n            <tr><td>X / Twitter</td><td class=\"mono\">\u2264 240 chars</td><td class=\"mono\">280 / 4000 premium</td><td>One idea per tweet. Threads for longer ideas.</td></tr>\n            <tr><td>LinkedIn</td><td class=\"mono\">700\u20131200 chars</td><td class=\"mono\">3000</td><td>Line breaks every 1\u20132 sentences. Hook in first 2 lines (before \"...see more\").</td></tr>\n            <tr><td>Instagram</td><td class=\"mono\">125\u2013400 chars</td><td class=\"mono\">2200</td><td>Hook in first line (rest collapses). Hashtags at end, separated by blank line.</td></tr>\n            <tr><td>TikTok</td><td class=\"mono\">80\u2013150 chars</td><td class=\"mono\">2200</td><td>Hashtags inline with sentence is fine.</td></tr>\n            <tr><td>Facebook</td><td class=\"mono\">\u2264 250 chars</td><td class=\"mono\">63206</td><td>Mirror LinkedIn but tighter.</td></tr>\n            <tr><td>YouTube description</td><td class=\"mono\">\u2265 250 words</td><td class=\"mono\">5000</td><td>Full description with timestamps, links, sponsor mentions. SEO matters here.</td></tr>\n          </tbody>\n        </table>\n\n        <h3 class=\"h-sub\">Hashtag ladders</h3>\n        <p>For each post, layer three hashtag types: <strong>brand</strong> (one), <strong>category</strong> (1\u20133), <strong>discovery</strong> (0\u20133, large communities).</p>\n\n        <h4 class=\"h-mini\">Brand hashtags</h4>\n        <div class=\"hash-grid\">\n          <div class=\"k\">For PrivexBot content</div>\n          <div class=\"v\"><code>#PrivexBot</code></div>\n          <div class=\"k\">For community spotlights</div>\n          <div class=\"v\"><code>#BuildWithPrivex</code></div>\n          <div class=\"k\">For build-in-public</div>\n          <div class=\"v\"><code>#PrivexBuildLog</code></div>\n        </div>\n\n        <h4 class=\"h-mini\">Category hashtags (pick 1\u20133)</h4>\n        <div class=\"hash-grid\">\n          <div class=\"k\">Privacy/security</div>\n          <div class=\"v\"><code>#privacy</code> <code>#confidentialcomputing</code> <code>#TEE</code> <code>#attestation</code> <code>#dataprivacy</code> <code>#zerotrust</code></div>\n          <div class=\"k\">AI</div>\n          <div class=\"v\"><code>#AI</code> <code>#GenAI</code> <code>#LLM</code> <code>#RAG</code> <code>#privateAI</code> <code>#OpenSourceAI</code></div>\n          <div class=\"k\">Build</div>\n          <div class=\"v\"><code>#buildinpublic</code> <code>#indiehackers</code> <code>#nocode</code> <code>#devtools</code></div>\n          <div class=\"k\">Industry</div>\n          <div class=\"v\"><code>#healthtech</code> <code>#fintech</code> <code>#legaltech</code> <code>#govtech</code> <code>#HIPAA</code> <code>#GDPR</code></div>\n        </div>\n\n        <h4 class=\"h-mini\">Per-platform hashtag count</h4>\n        <table class=\"std\">\n          <thead><tr><th>Platform</th><th>Count</th><th>Placement</th></tr></thead>\n          <tbody>\n            <tr><td>X / Twitter</td><td class=\"mono\">0\u20132</td><td>Inline if natural; never as a tag dump</td></tr>\n            <tr><td>LinkedIn</td><td class=\"mono\">3</td><td>End of post, on their own line</td></tr>\n            <tr><td>Instagram</td><td class=\"mono\">5\u20138</td><td>End of caption after a blank line, or as the first comment</td></tr>\n            <tr><td>TikTok</td><td class=\"mono\">3\u20135</td><td>Inline with the caption sentence</td></tr>\n            <tr><td>YouTube</td><td class=\"mono\">3</td><td>Above the title (display) + 5\u201310 in description</td></tr>\n          </tbody>\n        </table>\n\n        <h3 class=\"h-sub\">Banned hashtags</h3>\n        <p>Some hashtags do more harm than good \u2014 they signal \"marketing account\" or attract bot engagement. Never use:</p>\n        <ul class=\"std\">\n          <li><code>#follow4follow</code>, <code>#like4like</code>, anything in that family</li>\n          <li><code>#trending</code>, <code>#viral</code>, <code>#fyp</code> (TikTok auto-handles FYP; tagging it is amateur)</li>\n          <li><code>#crypto</code>, <code>#blockchain</code> as primary tags \u2014 we touch web3 audiences but we're not a crypto company</li>\n          <li>Any hashtag with caps lock or numbers-spelling-words (#AI4Good, #Web3Future)</li>\n          <li>Competitor brand names as hashtags</li>\n        </ul>\n\n        <h3 class=\"h-sub\">Same idea, three platforms</h3>\n\n        <div class=\"callout\">\n          <div class=\"callout-eyebrow\">X \u00b7 ~220 chars</div>\n          <p style=\"font-family:var(--font-mono); font-size:14px; line-height:1.6\">3 companies read your prompt before the model does:<br/><br/>\u00b7 the AI vendor (it's in their TOS)<br/>\u00b7 the model host (it's in their server logs)<br/>\u00b7 the network provider (it's in their analytics)<br/><br/>With PrivexBot: zero.<br/><br/>That's the only difference. It's a big one.</p>\n        </div>\n\n        <div class=\"callout\">\n          <div class=\"callout-eyebrow\">LinkedIn \u00b7 ~900 chars</div>\n          <p style=\"font-family:var(--font-mono); font-size:14px; line-height:1.6\">A note for compliance teams evaluating AI vendors:<br/><br/>When you send a message to a typical AI chatbot, three companies usually get to read it before the model generates a response. The AI vendor logs it for \"service improvement.\" The model host logs it in server analytics. The network provider may capture it in transit.<br/><br/>None of these companies are doing anything wrong. They're just doing what their TOS allows. The problem is that \"what TOS allows\" and \"what compliance teams in regulated industries can accept\" are two different things.<br/><br/>PrivexBot runs every inference inside a hardware-attested Trusted Execution Environment. We can't read your prompts. Neither can the model host. Neither can the network. And we give you a cryptographic receipt for every inference, so your compliance team can verify it independently.<br/><br/>If your vendor's privacy policy starts with \"we may use your data to improve our service,\" it's worth a conversation.<br/><br/>#privacy #AI #compliance</p>\n        </div>\n\n        <div class=\"callout\">\n          <div class=\"callout-eyebrow\">Instagram \u00b7 ~280 chars</div>\n          <p style=\"font-family:var(--font-mono); font-size:14px; line-height:1.6\">3 companies read your AI chatbot prompts before the model does \ud83d\udc40<br/><br/>1 \u2014 the AI vendor<br/>2 \u2014 the model host<br/>3 \u2014 the network provider<br/><br/>With PrivexBot: zero. We have receipts.<br/><br/>\ud83d\udc49 link in bio<br/><br/>.<br/>.<br/>.<br/>#PrivexBot #privateAI #privacy #TEE #attestation #buildinpublic #devtools #indiehackers</p>\n        </div>\n      </section>\n\n      <!-- ============= \u00a711 CADENCE ============= -->\n      <section id=\"cadence\" class=\"section\">\n        <div class=\"section-num\">\u00a7 11 \u00b7 Cadence</div>\n        <h2 class=\"h-section\">Show up consistently. Don't burn out.</h2>\n        <p class=\"lede\">A modest cadence we can hold for two years is worth more than a launch sprint we abandon in six weeks. The schedule below is the floor \u2014 beat it during launches, hold it the rest of the time.</p>\n\n        <h3 class=\"h-sub\">A typical week</h3>\n        <div class=\"cadence\">\n          <div class=\"cadence-head\">\n            <div></div><div>Mon</div><div>Tue</div><div>Wed</div><div>Thu</div><div>Fri</div><div>Sat</div><div>Sun</div>\n          </div>\n          <div class=\"cadence-row\">\n            <div>X</div>\n            <div class=\"cadence-cell\"><div class=\"pill pill-feed\">post</div>Privacy explainer</div>\n            <div class=\"cadence-cell\"><div class=\"pill pill-thread\">thread</div>Tutorial recap</div>\n            <div class=\"cadence-cell\"><div class=\"pill pill-feed\">post</div>Build-in-public</div>\n            <div class=\"cadence-cell\"><div class=\"pill pill-feed\">post</div>Hot take</div>\n            <div class=\"cadence-cell\"><div class=\"pill pill-feed\">post</div>Meme / Friday</div>\n            <div class=\"cadence-cell\" style=\"color:var(--ink-300)\">\u2014 off</div>\n            <div class=\"cadence-cell\" style=\"color:var(--ink-300)\">\u2014 off</div>\n          </div>\n          <div class=\"cadence-row\">\n            <div>LinkedIn</div>\n            <div class=\"cadence-cell\"><div class=\"pill pill-feed\">post</div>Long-form privacy</div>\n            <div class=\"cadence-cell\"></div>\n            <div class=\"cadence-cell\"><div class=\"pill pill-feed\">post</div>Customer story</div>\n            <div class=\"cadence-cell\"></div>\n            <div class=\"cadence-cell\"><div class=\"pill pill-feed\">post</div>Build / engineering</div>\n            <div class=\"cadence-cell\"></div>\n            <div class=\"cadence-cell\"></div>\n          </div>\n          <div class=\"cadence-row\">\n            <div>Instagram</div>\n            <div class=\"cadence-cell\"><div class=\"pill pill-story\">story</div>Tip</div>\n            <div class=\"cadence-cell\"><div class=\"pill pill-feed\">post</div>Carousel</div>\n            <div class=\"cadence-cell\"><div class=\"pill pill-story\">story</div>Behind scenes</div>\n            <div class=\"cadence-cell\"><div class=\"pill pill-feed\">post</div>Reel</div>\n            <div class=\"cadence-cell\"><div class=\"pill pill-story\">story</div>Question box</div>\n            <div class=\"cadence-cell\"><div class=\"pill pill-feed\">post</div>Quote / stat</div>\n            <div class=\"cadence-cell\"></div>\n          </div>\n          <div class=\"cadence-row\">\n            <div>YouTube</div>\n            <div class=\"cadence-cell\"></div>\n            <div class=\"cadence-cell\"><div class=\"pill pill-video\">video</div>Tutorial (14:00 UTC)</div>\n            <div class=\"cadence-cell\"></div>\n            <div class=\"cadence-cell\"></div>\n            <div class=\"cadence-cell\"></div>\n            <div class=\"cadence-cell\"></div>\n            <div class=\"cadence-cell\"></div>\n          </div>\n          <div class=\"cadence-row\">\n            <div>Twitch</div>\n            <div class=\"cadence-cell\"></div>\n            <div class=\"cadence-cell\"><div class=\"pill pill-stream\">live</div>2h build stream</div>\n            <div class=\"cadence-cell\"></div>\n            <div class=\"cadence-cell\"></div>\n            <div class=\"cadence-cell\"></div>\n            <div class=\"cadence-cell\"></div>\n            <div class=\"cadence-cell\"></div>\n          </div>\n          <div class=\"cadence-row\">\n            <div>TikTok</div>\n            <div class=\"cadence-cell\"></div>\n            <div class=\"cadence-cell\"></div>\n            <div class=\"cadence-cell\"><div class=\"pill pill-video\">video</div>Cut from YT</div>\n            <div class=\"cadence-cell\"></div>\n            <div class=\"cadence-cell\"><div class=\"pill pill-video\">video</div>Hot take</div>\n            <div class=\"cadence-cell\"></div>\n            <div class=\"cadence-cell\"></div>\n          </div>\n          <div class=\"cadence-row\">\n            <div>Facebook</div>\n            <div class=\"cadence-cell\"></div>\n            <div class=\"cadence-cell\"></div>\n            <div class=\"cadence-cell\"><div class=\"pill pill-feed\">post</div>Re-share LI</div>\n            <div class=\"cadence-cell\"></div>\n            <div class=\"cadence-cell\"><div class=\"pill pill-feed\">post</div>YouTube link</div>\n            <div class=\"cadence-cell\"></div>\n            <div class=\"cadence-cell\"></div>\n          </div>\n        </div>\n\n        <h3 class=\"h-sub\">Posting times</h3>\n        <p>Default to the audience timezone for each platform, not yours. The full spreadsheet of best slots lives in the team drive; the heuristic:</p>\n        <ul class=\"std\">\n          <li><strong>X:</strong> 09:00 + 16:00 ET, weekdays. Threads at 10:00 ET hold up best.</li>\n          <li><strong>LinkedIn:</strong> 08:00\u201310:00 ET, Mon/Wed/Fri.</li>\n          <li><strong>Instagram:</strong> 11:00 + 19:00 ET. Reels do well at 21:00 ET.</li>\n          <li><strong>YouTube:</strong> Drop Tuesday 14:00 UTC = breakfast US east coast, mid-day Europe.</li>\n          <li><strong>TikTok:</strong> 06:00 + 22:00 viewer-local (the platform splits across regions; scheduling tools handle this).</li>\n        </ul>\n\n        <h3 class=\"h-sub\">Sprint vs. baseline</h3>\n        <p>Two modes:</p>\n        <ul class=\"std\">\n          <li><strong>Baseline</strong> (~46 weeks/year) \u2014 cadence above. Sustainable forever.</li>\n          <li><strong>Sprint</strong> (~6 weeks/year, scheduled in advance) \u2014 2\u00d7 the post count, daily on every platform. Reserved for launch weeks, major customer announcements, conferences.</li>\n        </ul>\n        <p>Don't sprint without a sprint-justifying reason. \"It's been quiet\" is not a reason; quiet is fine.</p>\n\n        <h3 class=\"h-sub\">Reply &amp; engagement targets</h3>\n        <ul class=\"std\">\n          <li><strong>X mentions:</strong> respond within 4 hours (business hours), 24h max.</li>\n          <li><strong>LinkedIn comments:</strong> respond within 24 hours. Like every comment within 12.</li>\n          <li><strong>YouTube comments:</strong> within 48 hours; pin the best of each video.</li>\n          <li><strong>DMs:</strong> within 24h with a route to the right place (support, sales, docs).</li>\n        </ul>\n      </section>\n\n      <!-- ============= \u00a712 GUARDRAILS ============= -->\n      <section id=\"guardrails\" class=\"section\">\n        <div class=\"section-num\">\u00a7 12 \u00b7 Guardrails</div>\n        <h2 class=\"h-section\">The never-list.</h2>\n        <p class=\"lede\">A short list of things we don't do, ever. These exist to make decisions fast at 11pm before a launch.</p>\n\n        <div class=\"dod\">\n          <div class=\"do\">\n            <div class=\"head\">Always</div>\n            <ul>\n              <li>Verify privacy claims with engineering before posting (anything technical)</li>\n              <li>Get customer permission in writing before naming them</li>\n              <li>Sign founder/exec quotes with the real human</li>\n              <li>Run a contrast/accessibility check on every designed post</li>\n              <li>Spell PrivexBot correctly (auto-caption tools default to \"Privacy Bot\")</li>\n              <li>Time-stamp data (\"as of April 2026\") on any stat we cite</li>\n              <li>Disclose paid partnerships visibly (FTC + EU rules apply)</li>\n              <li>Archive every post in the social drive within 7 days</li>\n            </ul>\n          </div>\n          <div class=\"dont\">\n            <div class=\"head\">Never</div>\n            <ul>\n              <li>Screenshot customer prompts, even anonymised, even for explanatory purposes</li>\n              <li>Use stock photography</li>\n              <li>Make security claims we can't prove with attestation logs</li>\n              <li>Punch down at named competitors \u2014 punch at industry practices</li>\n              <li>Engage in political controversies that don't intersect AI privacy</li>\n              <li>Use AI-generated faces or voice for spokespeople; no AI \"team\" photos</li>\n              <li>Post during a major news tragedy without a 24h cooling period</li>\n              <li>Auto-DM new followers with a sales pitch</li>\n              <li>Buy followers, likes, comments, or engagement of any kind</li>\n              <li>Run \"tag 3 friends to win\" engagement-bait giveaways</li>\n              <li>Post about a customer outage before it's resolved + acknowledged on status page</li>\n            </ul>\n          </div>\n        </div>\n\n        <h3 class=\"h-sub\">Sensitive-topic protocol</h3>\n        <p>When a news event touches our space \u2014 a major AI privacy breach, a regulatory ruling, an industry incident \u2014 follow this:</p>\n        <ol class=\"std\">\n          <li><strong>Wait 24 hours.</strong> The first day is for journalists and victims, not vendors trying to capitalise.</li>\n          <li><strong>Check internally.</strong> Does this materially affect a customer? If yes, customer comms first.</li>\n          <li><strong>If we comment, comment substantively.</strong> Either we have something useful to say (an explainer, a position, a relevant feature) or we stay quiet. No \"thoughts and prayers\" + product link.</li>\n          <li><strong>Sign with a human</strong> if it's serious. Founder voice, not brand voice.</li>\n        </ol>\n\n        <h3 class=\"h-sub\">Crisis response (if we break or screw up)</h3>\n        <ol class=\"std\">\n          <li>Status page first, social second. Always.</li>\n          <li>Acknowledge fast. \"We're aware. Investigating. Update in 30 min.\" Don't speculate.</li>\n          <li>Post the resolution and the root cause publicly within 72 hours.</li>\n          <li>Don't delete the original incident post. Add an update; let the history stand.</li>\n          <li>Postmortem on the engineering blog within 2 weeks for anything that affected customer privacy or availability.</li>\n        </ol>\n\n        <h3 class=\"h-sub\">Legal &amp; compliance reminders</h3>\n        <ul class=\"std\">\n          <li><strong>HIPAA/PHI:</strong> never post anything that could be construed as patient data. Even a fake example from a healthcare customer needs legal review.</li>\n          <li><strong>GDPR:</strong> testimonials with EU customers require explicit written consent for the post and the platforms it will appear on.</li>\n          <li><strong>SOC2/ISO:</strong> we hold audit trails; treat customer logos and quotes as covered by our standard NDA \u2014 get the marketing rider signed.</li>\n          <li><strong>Financial claims:</strong> any revenue, ARR, or customer-count number must be approved by the CFO. \"Trusted by hundreds of teams\" is fine; \"$3.2M ARR\" needs sign-off.</li>\n        </ul>\n      </section>\n\n      <!-- ============= \u00a713 GOVERNANCE ============= -->\n      <section id=\"governance\" class=\"section\">\n        <div class=\"section-num\">\u00a7 13 \u00b7 Governance</div>\n        <h2 class=\"h-section\">Who owns what.</h2>\n        <p class=\"lede\">Roles, approvals, tools, review cycles. The playbook only works if the org around it works.</p>\n\n        <h3 class=\"h-sub\">Roles</h3>\n        <table class=\"std\">\n          <thead><tr><th>Role</th><th>Owns</th><th>Approval rights</th></tr></thead>\n          <tbody>\n            <tr><td>Brand lead</td><td>This playbook, the brand kit, visual consistency</td><td>Any change to thesis, voice, palette, logo system</td></tr>\n            <tr><td>Social lead</td><td>Calendar, posting cadence, daily replies, analytics</td><td>Posts in pillars 2\u20136; pillar 1 (privacy claims) requires eng review</td></tr>\n            <tr><td>DevRel</td><td>YouTube, Twitch, tutorials, technical accuracy</td><td>All technical/product feature posts</td></tr>\n            <tr><td>Founders</td><td>Manifesto / mission posts, big strategic statements</td><td>Anything quoting them; any post on a sensitive industry topic</td></tr>\n            <tr><td>Eng leads</td><td>Technical accuracy on TEE, attestation, security posts</td><td>Sign-off required on any privacy claim or threat-model statement</td></tr>\n            <tr><td>Legal/compliance</td><td>Risk on customer quotes, regulatory claims, comparative statements</td><td>Sign-off on customer stories, competitor comparisons, regulatory language</td></tr>\n          </tbody>\n        </table>\n\n        <h3 class=\"h-sub\">Approval flow</h3>\n        <ol class=\"std\">\n          <li><strong>Drafted in Notion</strong> (social \u2192 drafts board). Caption + visual + target platforms + scheduled date.</li>\n          <li><strong>Auto-routed for review</strong> based on pillar \u2014 privacy \u2192 eng, customer story \u2192 legal, etc.</li>\n          <li><strong>Approved drafts move to \"Queued\"</strong> column with publish date.</li>\n          <li><strong>Buffer / Hypefury</strong> picks up from \"Queued\" and ships on schedule.</li>\n          <li><strong>Published posts auto-log</strong> to the analytics dashboard with their pillar tag.</li>\n        </ol>\n\n        <h3 class=\"h-sub\">Tools</h3>\n        <table class=\"std\">\n          <thead><tr><th>Tool</th><th>Used for</th></tr></thead>\n          <tbody>\n            <tr><td>Notion</td><td>Drafts, approvals, calendar, this playbook</td></tr>\n            <tr><td>Buffer</td><td>Scheduling X, LinkedIn, IG, FB, TikTok</td></tr>\n            <tr><td>OBS + Twitch Studio</td><td>Live streams</td></tr>\n            <tr><td>Descript</td><td>Video editing for Reels/Shorts/TikTok cuts from YouTube</td></tr>\n            <tr><td>Brand kit (this repo)</td><td>Source of truth for templates and the post editor</td></tr>\n            <tr><td>Plausible Analytics</td><td>Web traffic attribution from social</td></tr>\n            <tr><td>Shield Analytics</td><td>LinkedIn-specific analytics</td></tr>\n          </tbody>\n        </table>\n\n        <h3 class=\"h-sub\">Review cycles</h3>\n        <ul class=\"std\">\n          <li><strong>Weekly:</strong> social lead reviews the past week's post performance; flags any post under the threshold for retro.</li>\n          <li><strong>Monthly:</strong> brand lead + social lead review pillar mix vs target. Adjust calendar if drift.</li>\n          <li><strong>Quarterly:</strong> full team review of the playbook itself. What rules helped? What rules got in the way? What changed in the world that breaks an assumption here?</li>\n          <li><strong>Annually:</strong> founders re-read the thesis section. If the company strategy moved, the thesis moves first; everything else follows.</li>\n        </ul>\n\n        <h3 class=\"h-sub\">Editing this document</h3>\n        <p>This playbook is versioned. Minor edits (a new banned hashtag, a tightened sentence, a corrected fact) ship in-place. Major changes (a new pillar, a removed platform, a voice shift) require a PR + brand-lead approval + a changelog entry at the bottom of this section.</p>\n\n        <div class=\"callout indigo\">\n          <div class=\"callout-eyebrow\">\u2192 Changelog</div>\n          <p style=\"font-family:var(--font-mono); font-size:13px; line-height:1.7\"><strong>v1.0 \u2014 May 2026</strong> \u00b7 Initial publication. Pairs with brand kit canvas v1.<br/><strong>\u2014</strong> Next planned review: <strong>Aug 2026</strong>.</p>\n        </div>\n\n        <div class=\"end-mark\">\n          <img src=\"/assets/icon-indigo.png\" alt=\"\" />\n          <span>END \u00b7 PRIVEXBOT SOCIAL PLAYBOOK \u00b7 v1</span>\n          <a href=\"/\">\u2197 Back to brand kit</a>\n        </div>\n      </section>\n\n      <!-- \u00a705\u2013\u00a713 INSERTED HERE -->\n\n    </div>\n  </main>\n</div>\n\n";

export default playbookHtml;
